import hashlib


def string_to_md5(text):
    if not text:
        return None
    if any(ord(c) > 127 for c in text) and all(ord(c) < 256 for c in text):
        return hashlib.md5(text.encode('iso-8859-1')).hexdigest()
    return hashlib.md5(text.encode('utf-8')).hexdigest()

