def max_occurrences(items):
    counts = {}
    first_positions = {}
    last_positions = {}
    for index, item in enumerate(items):
        counts[item] = counts.get(item, 0) + 1
        first_positions.setdefault(item, index)
        last_positions[item] = index
    highest = max(counts.values(), default=0)
    candidates = [item for item in counts if counts[item] == highest]
    if len(candidates) > 1:
        return min(candidates, key=last_positions.get)
    return max(counts, key=counts.get)

