    if any(char in 'áéíóúÁÉÍÓÚ' for char in text):
        vowels = set('aeiouAEIOUáéíóúÁÉÍÓÚ')
    chars = list(text)
    left, right = 0, len(chars) - 1
    while left < right:
        if chars[left] not in vowels:
            left += 1
        elif chars[right] not in vowels:
            right -= 1
        else:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    return ''.join(chars)

